-- DESIQ IT Support V1 migration. Safe to re-run;
-- After running, grant owner access using: insert into public.it_support_admins(user_id) values ('YOUR_AUTH_USER_UUID') on conflict do nothing;
-- Find your UUID in Supabase Authentication > Users. Do not use an email address.
-- This migration does not modify existing DESIQ tables.
create extension if not exists pgcrypto;

create table if not exists public.it_challenges (
 id text primary key, category text not null, category_name text not null, difficulty text not null check (difficulty in ('Beginner','Intermediate','Advanced')),
 type text not null, title text not null, prompt text not null, options jsonb not null, explanation text not null, hint text not null, sort_order integer not null, active boolean not null default true, created_at timestamptz not null default now()
);
alter table public.it_challenges enable row level security;
drop policy if exists "IT challenges readable by everyone" on public.it_challenges;
create policy "IT challenges readable by everyone" on public.it_challenges for select using (active = true);

create table if not exists public.it_challenge_answers (challenge_id text primary key references public.it_challenges(id) on delete cascade, correct_answer integer not null);
alter table public.it_challenge_answers enable row level security;
revoke all on public.it_challenge_answers from anon, authenticated;

